  "steps": [
    {
      "id": 1,
      "claim": "The bystander's prior statement is an out‑of‑court statement offered to prove the color of the traffic signal.",
      "evidence": "The prior statement says the witness was not sure if the signal was yellow or red, which is being used to challenge the truth of his current testimony.",
      "weight": 0.25,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Out‑of‑court statements are generally hearsay and inadmissible as substantive evidence unless an exception applies.",
      "evidence": "Federal Rules of Evidence 802 (hearsay rule) and common‑law hearsay principles.",
      "weight": 0.25,
      "depends_on": []
    },
    {
      "id": 3,
      "claim": "A prior inconsistent statement is admissible for the purpose of impeaching a witness’s credibility, but not as substantive evidence, unless it falls under a specific exception.",
      "evidence": "FRE 613; case law holding that prior inconsistent statements are limited to credibility attacks.",
      "weight": 0.30,
      "depends_on": [1, 2]
    },
    {
      "id": 4,
      "claim": "The bystander's prior statement does not meet any substantive‑evidence exception (it is not a party admission, present sense impression, etc.).",
      "evidence": "The statement is merely the witness’s personal recollection to a friend, not a statement against interest or other recognized exception.",
      "weight": 0.10,
      "depends_on": [2]
    },
    {
      "id": 5,
      "claim": "Therefore the trial judge should limit the use of the prior statement to impeachment and instruct the jury that it cannot be considered substantive evidence.",
      "evidence": "Application of the rule in step 3 to the facts; the correct remedy is a limiting instruction.",
      "weight": 0.10,
      "depends_on": [3, 4]
    }
  ],
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "Would allow the prior statement as substantive evidence, violating the hearsay rule."
    },
    {
      "answer": "B",
      "reason_rejected": "While a witness could be called to prove the prior statement was made, the judge’s primary duty is to give the proper limiting instruction; calling additional witnesses is unnecessary."
    },
    {
      "answer": "C",
      "reason_rejected": "Disregarding the bystander's testimony altogether is too drastic; the testimony is admissible, only its credibility is in question."
    }
  ]
}
